def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Get contiguous, non-background runs on each of the four borders.
    def runs(side):
        if side in ("top", "bottom"):
            r = 0 if side == "top" else h - 1
            vals = grid[r]
        else:
            c = 0 if side == "left" else w - 1
            vals = [grid[r][c] for r in range(h)]

        result = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            result.append((i, j, color))  # half-open interval
            i = j
        return result

    # Locate a pair of equal-length, same-colored runs on opposing borders.
    candidates = []
    for side_a, side_b, orientation in (
        ("top", "bottom", "horizontal"),
        ("left", "right", "vertical"),
    ):
        for a in runs(side_a):
            for b in runs(side_b):
                if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                    candidates.append((a[1] - a[0], side_a, side_b, a, b, orientation))

    if not candidates:
        return [row[:] for row in grid]

    _, side_a, side_b, seg_a, seg_b, orientation = max(candidates)

    out = [row[:] for row in grid]
    bars = set()
    for side, seg in ((side_a, seg_a), (side_b, seg_b)):
        for t in range(seg[0], seg[1]):
            if side == "top":
                bars.add((0, t))
            elif side == "bottom":
                bars.add((h - 1, t))
            elif side == "left":
                bars.add((t, 0))
            else:
                bars.add((t, w - 1))

    # Each isolated marker extends back to its aligned border run.
    # At the corresponding position on the opposite border, its color
    # extends all the way across the grid.
    markers = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != bg and (r, c) not in bars
    ]

    for r, c, color in markers:
        t = c if orientation == "horizontal" else r

        if seg_a[0] <= t < seg_a[1]:
            source_side, source_seg = side_a, seg_a
            other_side, other_seg = side_b, seg_b
        elif seg_b[0] <= t < seg_b[1]:
            source_side, source_seg = side_b, seg_b
            other_side, other_seg = side_a, seg_a
        else:
            continue

        offset = t - source_seg[0]
        mapped_t = other_seg[0] + offset

        # Fill between the marker and its associated border, leaving the
        # marker itself to be recolored as the endpoint.
        if orientation == "horizontal":
            edge_r = 0 if source_side == "top" else h - 1
            step = 1 if r > edge_r else -1
            rr = edge_r + step
            while rr != r:
                if out[rr][c] == bg:
                    out[rr][c] = color
                rr += step
        else:
            edge_c = 0 if source_side == "left" else w - 1
            step = 1 if c > edge_c else -1
            cc = edge_c + step
            while cc != c:
                if out[r][cc] == bg:
                    out[r][cc] = color
                cc += step

        out[r][c] = 4

        # Draw the corresponding full stripe from the opposite border.
        if orientation == "horizontal":
            for rr in range(h):
                if (rr, mapped_t) not in bars and out[rr][mapped_t] == bg:
                    out[rr][mapped_t] = color
        else:
            for cc in range(w):
                if (mapped_t, cc) not in bars and out[mapped_t][cc] == bg:
                    out[mapped_t][cc] = color

    return out
